<span class="line"><span style="color:#ABB2BF;">await </span><span style="color:#C678DD;">using</span><span style="color:#C678DD;"> var</span><span style="color:#E06C75;"> connection</span><span style="color:#56B6C2;"> =</span><span style="color:#ABB2BF;"> await </span><span style="color:#E5C07B;">factory</span><span style="color:#ABB2BF;">.</span><span style="color:#61AFEF;">CreateConnectionAsync</span><span style="color:#ABB2BF;">();</span></span>
